import {lazy,Suspense,useState} from 'react';
import {Search,ShoppingBag,Package,ArrowUpRight,ArrowRight,Store,Truck} from 'lucide-react';
import {Drawer,Field,Form} from './ui';
import {Blank,Feedback,Section} from './common';
import {money,platform,useResource} from './data';
import Orders from './Orders';
import NetworkScene from './NetworkScene';
const StorefrontReviews=lazy(()=>import('./Community').then(m=>({default:m.StorefrontReviews})));
export default function Consumer({onOrders}){
 const [query,setQuery]=useState(''),[organization,setOrganization]=useState(''),[cart,setCart]=useState(false),[selected,setSelected]=useState(null),[error,setError]=useState(''),[notice,setNotice]=useState(''),[ordersRevision,setOrdersRevision]=useState(0);
 const r=useResource(async()=>{const {organizations}=await platform('/organizations');return{organizations:organizations.filter(o=>o.status==='approved')};});
 const catalog=useResource(async()=>{if(!organization)return {products:[]};const {products}=await platform(`/organizations/${organization}/products`);return{products:products.map(p=>({...p,organization:r.data?.organizations.find(o=>o.id===organization)?.name??''}))};},[organization]);
 const products=catalog.data?.products.filter(p=>p.organization_id===organization&&`${p.name} ${p.description??''}`.toLowerCase().includes(query.toLowerCase()))??[];
 const add=async p=>{try{setError('');const current=(await platform('/cart')).items.find(item=>item.product_id===p.id);await platform('/cart','POST',{productId:p.id,quantity:(current?.quantity??0)+1});setCart(true);}catch(e){setError(e.message);}};
 return <>{!organization?<section className="discover-hero"><div className="hero-copy"><h1>Your community.<br/><span>Closer</span> than ever.</h1><p>Discover organizations, explore their stores, and follow every delivery.</p><div className="hero-actions"><button className="primary" onClick={()=>{document.getElementById('organization-search')?.focus();document.getElementById('organization-directory')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}>Explore organizations <ArrowRight size={18}/></button><button className="secondary" onClick={onOrders}>My orders</button></div></div><div className="hero-visual"><NetworkScene compact/></div></section>:<div className="page-heading"><div><h1>{r.data?.organizations.find(o=>o.id===organization)?.name}</h1><p>Explore this store and find what you need.</p></div></div>}<div className="discovery-tools"><div className="catalog-filters"><label className="search-input"><Search size={21}/><input id="organization-search" aria-label={organization?"Search this store":"Search organizations"} placeholder={organization?"Search this store":"Search organizations"} value={query} onChange={e=>setQuery(e.target.value)}/></label>{organization?<button className="secondary" onClick={()=>{setOrganization('');setQuery('');}}>All organizations</button>:null}</div><button aria-label="Your cart" className="secondary cart-button" onClick={()=>setCart(true)}><ShoppingBag size={18}/><span>Your cart</span></button></div><Feedback resource={r}/>{organization?<Feedback resource={catalog}/>:null}{notice?<p role="status" className="notice">{notice}</p>:null}{error?<p role="alert" className="error">{error}</p>:null}{r.data&&!organization?<div id="organization-directory"><Section title="Organizations" action={<span className="section-note">Stores in your community</span>}><div className="organization-grid">{r.data.organizations.filter(o=>`${o.name} ${o.about??''}`.toLowerCase().includes(query.toLowerCase())).map(o=><button className="organization-card" key={o.id} aria-label={`Open ${o.name} store`} title={o.name} onClick={()=>{setOrganization(o.id);setQuery('');}}>{o.logo?<img src={o.logo} alt={`${o.name} logo`}/>:<span className="organization-logo" aria-hidden="true"><Store size={44} strokeWidth={1.35}/></span>}<span className="organization-name">{o.name}<ArrowUpRight size={16}/></span></button>)}</div>{!r.data.organizations.length?<Blank title="No organizations yet.">Stores will appear here when managers register them.</Blank>:null}{r.data.organizations.length&&!r.data.organizations.some(o=>`${o.name} ${o.about??''}`.toLowerCase().includes(query.toLowerCase()))?<Blank title="No matching organizations."/>:null}</Section></div>:null}{r.data&&organization?<Section title="Store products"><div className="product-grid">{products.map(p=><article className="product-card" key={p.id}><button className="product-art" aria-label={`View ${p.name}`} onClick={()=>setSelected(p)}>{p.image?<img src={p.image} alt={p.name}/>:<Package size={54} strokeWidth={1}/>}<span>{p.organization}</span><ArrowUpRight size={20}/></button><div className="product-info"><p className="small muted"><Store size={14}/>{p.organization}</p><button className="product-title" onClick={()=>setSelected(p)}>{p.name}</button><div className="product-price"><strong>{money(p.price_minor,p.currency)}</strong><span>{p.stock?`${p.stock} available`:'Out of stock'}</span></div><button className="primary" disabled={!p.stock} onClick={()=>add(p)}><ShoppingBag size={16}/>Add to cart</button></div></article>)}</div>{!products.length?<Blank title={query||organization?'No matching products.':'No products available yet.'}>{query||organization?'Try another search or organization.':'Products will appear after an approved organization publishes them.'}</Blank>:null}</Section>:null}{selected?<Drawer title="Product details" onClose={()=>setSelected(null)}><div className="product-detail-art">{selected.image?<img src={selected.image} alt={selected.name}/>:<Package size={80} strokeWidth={1}/>}</div><p className="small muted">{selected.organization}</p><h2>{selected.name}</h2><p>{selected.description}</p><p className="product-detail-price">{money(selected.price_minor,selected.currency)}</p><p className="small muted">{selected.stock} available · Product payment is separate from delivery.</p><button className="primary" disabled={!selected.stock} onClick={async()=>{await add(selected);setSelected(null);}}>Add to cart</button><div className="delivery-note"><Truck size={20}/><div><strong>Delivery payment on arrival</strong><p>Choose cash or digital delivery payment at checkout. Live rates are not configured.</p></div></div><Suspense fallback={<p role="status">Loading public reviews…</p>}><StorefrontReviews id={selected.organization_id} productId={selected.id}/></Suspense></Drawer>:null}{organization?<StorefrontReviews key={organization} id={organization}/>:null}<Orders compact key={ordersRevision}/>{cart?<Cart onPlaced={result=>{setNotice(`Sandbox order ${result.id.slice(0,8)} placed. Open My orders for delivery details.`);setOrdersRevision(value=>value+1);void r.refresh();}} onClose={()=>{setCart(false);void r.refresh();}}/>:null}</>;
}
function Cart({onClose,onPlaced}){
 const r=useResource(async()=>{const [cart,addresses]=await Promise.all([platform('/cart'),platform('/addresses')]);return{...cart,...addresses};}),[notice,setNotice]=useState('');
 const update=async(id,quantity)=>{await platform('/cart','POST',{productId:id,quantity});await r.refresh();};
 return <Drawer title="Your cart" onClose={onClose}><Feedback resource={r}/>{r.data?<>{r.data.items.length?<><ul className="line-list">{r.data.items.map(p=><li key={p.product_id}><div><strong>{p.name}</strong><p>{money(p.price_minor,p.currency)} each</p><Form submit="Update quantity" onSubmit={d=>update(p.product_id,Number(d.quantity))}><Field label={`Quantity for ${p.name}`} type="number" name="quantity" min="0" max="100" required defaultValue={p.quantity}/></Form></div><strong>{money(p.price_minor*p.quantity,p.currency)}</strong></li>)}</ul><p className="small muted">One organization and currency per order. Set quantity to zero to remove a product.</p><div className="settlement-card"><span className="step-number">01</span><div><h3>Product payment</h3><p>Digital payment at checkout</p>{[...new Set(r.data.items.map(p=>p.currency))].map(currency=><strong key={currency}>{money(r.data.items.filter(p=>p.currency===currency).reduce((total,p)=>total+p.price_minor*p.quantity,0),currency)}</strong>)}</div></div><div className="settlement-card"><span className="step-number">02</span><div><h3>Delivery payment</h3><p>Separate, on arrival · Fare not configured</p></div></div><h3>Checkout</h3><p className="notice">Sandbox checkout only. Product payment is simulated digital payment. No real charges, delivery fare or bank debit is enabled.</p>{r.data.addresses.length?<Form submit="Place sandbox order" onSubmit={async d=>{const result=await platform('/orders','POST',d);setNotice(`Sandbox order ${result.id.slice(0,8)} placed. Open My orders for delivery details.`);onPlaced(result);await r.refresh();}}><Field label="Delivery destination"><select name="addressId" required>{r.data.addresses.map(a=><option key={a.id} value={a.id}>{a.label} — {a.address}</option>)}</select></Field><Field label="Delivery payment on arrival"><select name="deliveryPayment"><option value="cash">Cash on arrival</option><option value="digital">Sandbox digital on arrival</option></select></Field></Form>:<p className="error">Add your delivery address in Delivery map before checkout.</p>}</>:<Blank title="Your cart is empty.">Add a product to begin your order.</Blank>}{notice?<p role="status" className="notice">{notice}</p>:null}</>:null}</Drawer>;
}
